// Runtime catalogue loading. Files are generated by scripts/build-data.mjs.

export interface StarCatalog {
  count: number;
  ra: number[];
  dec: number[];
  mag: number[];
  ci: (number | null)[];
  dist: (number | null)[];
  absmag: (number | null)[];
  spect: string[];
  name: string[];
  desig: string[];
  con: string[];
  hip: (number | null)[];
}

export interface HRSample {
  count: number;
  ci: number[];
  M: number[];
  name: string[];
}

export interface ExoplanetCatalog {
  count: number;
  methods: string[];
  name: string[];
  method: number[];
  year: number[];
  mass: (number | null)[];
  radius: (number | null)[];
  period: (number | null)[];
  a: (number | null)[];
  e: (number | null)[];
  teq: (number | null)[];
  dist: (number | null)[];
  smass: (number | null)[];
  sradius: (number | null)[];
  steff: (number | null)[];
  sfeh: (number | null)[];
  ra: (number | null)[];
  dec: (number | null)[];
}

/** [gx, gy, gz, absmag, ci, spect, name, desig, mag, dist, planets] — galactic cartesian, parsecs */
export type NearbyStar = [number, number, number, number, number | null, string, string, string, number, number, number];
export interface NearbyCatalog {
  count: number;
  radius: number;
  stars: NearbyStar[];
}

export interface Constellation {
  id: string;
  name: string;
  gen: string;
  rank: number;
  ra: number;
  dec: number;
}
export interface ConstellationData {
  list: Constellation[];
  lines: Record<string, [number, number][][]>;
  borders: number[][];
}

export interface MilkyWayData {
  levels: number[][][][];
}

export interface MessierObject {
  id: string;
  name: string;
  ngc: string;
  type: string;
  kind: string;
  mag: number;
  dim: string;
  ra: number;
  dec: number;
}

const cache = new Map<string, Promise<unknown>>();

function load<T>(file: string): Promise<T> {
  let p = cache.get(file) as Promise<T> | undefined;
  if (!p) {
    p = fetch(new URL(`data/${file}`, document.baseURI).href).then((r) => {
      if (!r.ok) throw new Error(`Could not load data/${file} (HTTP ${r.status}).`);
      return r.json() as Promise<T>;
    });
    p.catch(() => cache.delete(file));
    cache.set(file, p);
  }
  return p;
}

export const loadStars = () => load<StarCatalog>('stars.json');
export const loadHR = () => load<HRSample>('hr.json');
export const loadExoplanets = () => load<ExoplanetCatalog>('exoplanets.json');
export const loadNearby = () => load<NearbyCatalog>('nearby.json');
export const loadConstellations = () => load<ConstellationData>('constellations.json');
export const loadMilkyWay = () => load<MilkyWayData>('milkyway.json');
export const loadMessier = () => load<MessierObject[]>('messier.json');
